        public static string maybeThrow(bool flag){ if(flag) throw new Exception("boom"); return "ok"; }
    }
    '''


def gen_tags_and_sources() -> List[Tuple[str, callable]]:
    return [
        ("py", gen_python),
        ("python", gen_python),
        ("node", gen_node),
        ("js", gen_node),
        ("ts", gen_ts),
        ("rb", gen_ruby),
        ("wasm", gen_wasm_wat),
        ("wat", gen_wasm_wat),
        ("cs", gen_csharp),
    ]


def choose_tag(rand: random.Random) -> Tuple[str, str]:
    entries = gen_tags_and_sources()
    tag, gen = rand.choice(entries)
    src = gen(rand)
    return tag, src


def maybe_variants(tag: str, src: str, rand: random.Random) -> str:
    # Produce variants to trigger different loader paths while keeping validity
    # - Prepend shebangs or pragmas sometimes
    # - Append harmless comments or whitespace
    prefix = ""
    suffix = ""
    if tag in ("py", "python") and rand.random() < 0.4:
        prefix = "#!/usr/bin/env python3\n"
    if tag in ("js", "node", "ts") and rand.random() < 0.4:
        prefix = "// metacall test\n" + prefix
    if tag in ("rb",) and rand.random() < 0.3:
        prefix = "# frozen_string_literal: true\n" + prefix
    # Add trailing newlines/comments to alter size and hashing but keep semantics
    if rand.random() < 0.7:
        suffix = "\n" * rand.randint(1, 4)
    if rand.random() < 0.5:
        suffix += ("\n// eof\n" if tag in ("js", "node", "ts") else "\n# eof\n")
    return prefix + src + suffix


def assemble(tag: str, src: str) -> bytes:
    # First line is the tag, then NUL, then script. The stub only uses buf and tag
    # separately via FUZZ_PARAM_STR; many fuzzing harnesses can split, but even if not,
    # providing a clear tag+payload structure is safe. Ensure <= MAX_SIZE.
    blob = (tag + "\n\x00").encode('utf-8') + src.encode('utf-8')
    return blob[:MAX_SIZE]


def generate(seed: int) -> bytes:
    rand = random.Random(seed)
    tag, src = choose_tag(rand)
    src = maybe_variants(tag, src, rand)
    return assemble(tag, src)
